package org.firstinspires.ftc.teamcode.subsystems;

import com.pedropathing.math.Pose;

import org.firstinspires.ftc.teamcode.config.Field;
import org.firstinspires.ftc.teamcode.config.MatchState;
import org.firstinspires.ftc.teamcode.config.Tuned;

// Generated by refract-suite ftc-construct. Solves both launchers against the own-alliance CELL on the
// robot's side of y = 72. Each turret has its own yaw servo, so each aims from its own pivot. A launcher whose turret
// cannot reach the CELL does not fire (its gate stays shut); the solution is valid while at least one can.
// No shot lead: the robot is stopped when it fires (R102 practice, team 2026-10-17).
public final class AutoAim {
    public static final class Solution {
        public boolean valid = false;
        public String problem = "";
        public double cellX, cellY;
        public double frontDistance, backDistance;
        public double frontYawDeg, backYawDeg;      // each turret's own angle relative to the robot
        public double frontErrorDeg, backErrorDeg;  // where each turret is minus where it should be
        public boolean frontReachable, backReachable;
        public boolean frontLocked, backLocked;
        public boolean locked;                      // every reachable turret is on target
        public boolean solved;                      // geometry computed (may still be invalid: both out of travel)

        // this launcher fires on a shot: its turret can reach the CELL
        public boolean fires(int side) {
            return valid && (side == Yaw.FRONT ? frontReachable : backReachable);
        }
    }

    private AutoAim() {}

    public static double distance(double fromX, double fromY, double toX, double toY) {
        return Math.hypot(toX - fromX, toY - fromY);
    }

    public static double[] pivot(Pose pose, double bodyX, double bodyY) {
        double c = Math.cos(pose.heading()), s = Math.sin(pose.heading());
        return new double[]{pose.x() + c * bodyX - s * bodyY, pose.y() + s * bodyX + c * bodyY};
    }

    // half the angle the 20 in CELL opening subtends at this distance
    public static double toleranceDeg(double distance) {
        return 0.5 * Math.toDegrees(Math.atan(Field.CELL_HALF_WIDTH / distance));
    }

    // currentFrontDeg / currentBackDeg: where each turret is (Yaw.deg); NaN = not known, never locked
    public static Solution solve(Pose pose, MatchState.Alliance alliance, double currentFrontDeg, double currentBackDeg,
                                 double distanceTrim, double angleTrimDeg) {
        Solution s = new Solution();
        if (alliance == null) return fail(s, "alliance unknown (INIT the correct auto, or pick in teleop INIT)");
        if (!Tuned.isSet(Tuned.frontPivotX, Tuned.frontPivotY, Tuned.backPivotX, Tuned.backPivotY)) {
            return fail(s, "turret pivot offsets not set (C-3)");
        }
        if (!Yaw.calibrated()) return fail(s, "turret servos not measured (program 3)");
        double[] cell = Field.targetCell(alliance, pose.y());
        if (!Tuned.isSet(cell[0], cell[1])) return fail(s, "CELL coordinates not set (H-1)");
        s.cellX = cell[0];
        s.cellY = cell[1];

        double[] fp = pivot(pose, Tuned.frontPivotX, Tuned.frontPivotY);
        double[] bp = pivot(pose, Tuned.backPivotX, Tuned.backPivotY);
        s.frontDistance = distance(fp[0], fp[1], cell[0], cell[1]) + distanceTrim;
        s.backDistance = distance(bp[0], bp[1], cell[0], cell[1]) + distanceTrim;
        // + the yaw trim each launcher scored with in programs 8 / 9 (its own turret degrees)
        s.frontYawDeg = Field.wrapDeg(Math.toDegrees(Math.atan2(cell[1] - fp[1], cell[0] - fp[0]) - pose.heading())) + angleTrimDeg + trim(Tuned.frontYawTrimDeg);
        s.backYawDeg = Field.wrapDeg(Math.toDegrees(Math.atan2(cell[1] - bp[1], cell[0] - bp[0]) - pose.heading())) + angleTrimDeg + trim(Tuned.backYawTrimDeg);
        s.frontReachable = Yaw.inLimits(Yaw.FRONT, s.frontYawDeg);
        s.backReachable = Yaw.inLimits(Yaw.BACK, s.backYawDeg);

        s.frontErrorDeg = currentFrontDeg - s.frontYawDeg;
        s.backErrorDeg = currentBackDeg - s.backYawDeg;
        s.frontLocked = s.frontReachable && Math.abs(s.frontErrorDeg) <= toleranceDeg(s.frontDistance);
        s.backLocked = s.backReachable && Math.abs(s.backErrorDeg) <= toleranceDeg(s.backDistance);
        s.solved = true;
        if (!s.frontReachable && !s.backReachable) return fail(s, "CELL outside both turrets' travel: turn the robot");
        s.locked = (!s.frontReachable || s.frontLocked) && (!s.backReachable || s.backLocked);
        s.valid = true;
        return s;
    }

    // A yaw trim past this is not aim error but a wrong forward position (program 3): never saved, never used
    public static final double MAX_TRIM_DEG = 10;

    // no trim measured yet = none; an old one past MAX_TRIM_DEG (saved before that check) = none
    private static double trim(double deg) {
        return Double.isNaN(deg) || Math.abs(deg) > MAX_TRIM_DEG ? 0 : deg;
    }

    public static Solution invalid(String why) {
        return fail(new Solution(), why);
    }

    private static Solution fail(Solution s, String why) {
        s.valid = false;
        s.locked = false;
        s.problem = why;
        return s;
    }
}
